#!/usr/bin/env bash
# Full red-green-refactor eval on post-cutoff srvx commits. Usage: run-rgr.sh [--dry-run] <task> <arm> <k> [...]
# arm a = packaged lz-tdd only; arm b = same + the Test-first rule folder generated by ../slim-arms.sh.
# Each run gets a fresh copy of the task's template (the commit's parent), its own pnpm install and a base commit, so
# the grader can diff what the session changed. Sessions run one at a time.
here="$(cygpath -m "$(cd "$(dirname "$0")" && pwd)")"
. "$here/../slim-arms.sh"
ALLOW='Skill Read Edit Write Glob Grep Bash(npx vitest*) Bash(NO_COLOR=1 npx vitest*) Bash(npx tsc*) Bash(ls *) Bash(cat *) Bash(git diff*) Bash(git status*)'
DENY='Skill(lars-mode) Skill(lz.windows:deny-bash-commands) Skill(lz.windows:reset-bash-commands) WebFetch WebSearch'
# MODEL and PROMPT override the model and the prompt file (prompts/<PROMPT>.md) for the setup control.
model=${MODEL:-opus}
dry=()

if [ "${1:-}" = --dry-run ]; then
  dry=(--dry-run)
  shift
fi

ensure_pkg || exit 1
ensure_rules_b || exit 1
mkdir -p "$here/out"

while [ $# -ge 3 ]; do
  task=$1 arm=$2 k=$3
  shift 3
  root="$slim_root/rgr-eval/$task"
  dir="$root/runs/$arm-$k"
  rm -rf "$dir"
  mkdir -p "$dir"
  (cd "$root/template" && tar -cf - --exclude=node_modules .) | (cd "$dir" && tar -xf -)
  (cd "$dir" && pnpm install --frozen-lockfile --prefer-offline --silent \
    && git init -q && git add -A && git -c user.name=eval -c user.email=eval@localhost commit -qm base && git tag base) \
    || { echo "== $task $arm $k setup failed"; continue; }

  if [ "$arm" = b ]; then
    rules="$rules_b"
  else
    rules=none
  fi

  begin_cycle_logs "$dir"
  node "$HOME/.claude/references/slim-claude-p/run-slim.ts" --cwd "$dir" --prompt-file "$here/prompts/${PROMPT:-$task}.md" \
    --out "$here/out/run-$task-$arm-$k.json" --plugin-dir "$pkg_dir" --rules "$rules" --model "$model" \
    --timeout-min 30 --allow "$ALLOW" --deny "$DENY" "${dry[@]}"
  status=$?
  collect_cycle_logs "$dir"
  echo "== $task $arm $k exit=$status"

  # A spend-limit hit fails in seconds; stop the queue rather than turn one failure into many.
  if [ "$status" -ne 0 ]; then
    echo "[ERROR] stopping the queue after $task $arm $k"
    exit 1
  fi
done
